import re, numpy, math
from mpmath import mp, mpf
from matplotlib import pyplot

mp.dps = 10000

reference = mpf('0.')
#2450 13894 [0. +/- 8.51e-2468]

raw_data = open('results.txt').read()

def match_count(a: str, b: str) -> int:
    return next(
        (i for i, (x, y) in enumerate(zip(a, b)) if x != y),
        min(len(a), len(b)),
    )

def decimal_digits(value: str) -> str:
    # Compare fractional digits only, ignoring the leading "0.".
    value = value.strip()
    if value.startswith("0."):
        return value[2:]
    raise ValueError(f"Unexpected decimal format: {value}")

data = []

for line in raw_data.splitlines():
    line = line.strip()
    if not line:
        continue

    match = re.fullmatch(
        r"(\d+)\s+(\d+)\s+\[\s*(.*?)\s+\+/-\s+([^\]]+)\]",
        line,
    )
    if not match:
        raise ValueError(f"Cannot parse line: {line}")

    precision = int(match.group(1))
    iterations = int(match.group(2))
    midpoint = match.group(3)
    radius = match.group(4)

    data.append((precision, iterations, mpf(midpoint), radius))

reference_digits = decimal_digits(mp.nstr(reference, n=mp.dps))

precisions = []
itercounts = []
match_counts = []
match_ratios = []

for precision, iterations, value, radius in data:
    value_digits = decimal_digits(mp.nstr(value, n=mp.dps))
    matches = match_count(reference_digits, value_digits)

    precisions.append(precision)
    itercounts.append(iterations)
    match_counts.append(matches)
    #match_ratios.append(matches / (precision - matches))
    match_ratios.append(matches / precision)

pyplot.plot(precisions, itercounts, label="iterations")
pyplot.plot(precisions, match_counts, label="matching fractional digits")
pyplot.xlabel("Requested precision (decimal digits)")
pyplot.legend()
pyplot.show()

#pyplot.plot(precisions, match_ratios, label="matching digits / (requested precision - matching digits)")
pyplot.plot(precisions, match_ratios, label="matching digits / requested precision")
pyplot.xlabel("Requested precision (decimal digits)")
pyplot.ylabel("Match ratio")
pyplot.legend()
pyplot.show()

for (precision, iterations, value, radius), matches, ratio in zip(
    data, match_counts, match_ratios
):
    print(
        f"{precision:5} dps | {iterations:6} iterations | "
        f"{matches:5} matching digits | ratio {ratio:.4f} | "
        f"radius {radius}"
    )

